import assert from 'node:assert/strict';import {W04ReviewDomain,createReviewsCompareProvider} from '../../../adapters/reviews/domain.js';import {AnalyticalCompareOwner} from '../../../foundation/analytical/compare.js';
const d=new W04ReviewDomain();assert.equal(d.familyAdmissionClaim,false);assert.equal(d.reviewDecisionPresentationStatus,'CONCEPT_CONTRACT_ONLY');const before=d.inspect('review-1');const closed=d.supersede('review-1',{expectedDecisionId:'wrong',newDecision:{decisionId:'d-new',outcome:'ACCEPT'}});assert.equal(closed.code,'REVIEW_NOT_READY_FOR_DECISION');assert.equal(d.inspect('review-1').decision.decisionId,before.decision.decisionId);d.setAuthority('review-2',false);const blocked=d.finding('review-2',{findingId:'f-x',text:'x'});assert.equal(blocked.code,'REVIEWER_AUTHORITY_UNAVAILABLE');const snap=d.presentationSnapshot('review-2');assert.equal(snap.authorityCeiling,'NO_FORMAL_DECISION_AUTHORITY_OR_MUTATION');assert.equal(snap.familyStatus,'CONCEPT_CONTRACT_ONLY');const ac=new AnalyticalCompareOwner(),p=createReviewsCompareProvider(d);ac.registerProvider(p);const a=d.records[0],b=d.records[1],pair=ac.createPair({left:{providerId:p.descriptor().providerId,ref:{id:a.id,revisionId:a.revisionId}},right:{providerId:p.descriptor().providerId,ref:{id:b.id,revisionId:b.revisionId}}});assert.notEqual(ac.comparePair(pair).state,'ERROR');console.log(JSON.stringify({surface:'reviews',pass:true,gatePs003Claim:d.familyAdmissionClaim,presentationFamily:d.reviewDecisionPresentationStatus}));
